<?php require_once __DIR__.'/bootstrap.php';$title='AniRead — Discover your next story';$description='Discover anime metadata and authorized sources on AniRead.';$sections=[];$queries=['Trending'=>'SELECT * FROM anime ORDER BY popularity IS NULL,popularity ASC LIMIT 12','Top Rated'=>'SELECT * FROM anime WHERE score IS NOT NULL ORDER BY score DESC LIMIT 12','Top Airing'=>"SELECT * FROM anime WHERE status='Currently Airing' ORDER BY popularity IS NULL,popularity ASC LIMIT 12",'Current Season'=>"SELECT * FROM anime WHERE year=YEAR(CURDATE()) AND season IN ('winter','spring','summer','fall') ORDER BY popularity IS NULL,popularity ASC LIMIT 12",'Upcoming'=>"SELECT * FROM anime WHERE status='Not yet aired' ORDER BY aired_from ASC LIMIT 12",'Movies'=>"SELECT * FROM anime WHERE type='Movie' ORDER BY popularity IS NULL,popularity ASC LIMIT 12",'Recently Added'=>'SELECT * FROM anime ORDER BY created_at DESC LIMIT 12'];foreach($queries as $name=>$sql){$r=$pdo->query($sql)->fetchAll();if($r)$sections[$name]=$r;}$featured=$sections['Trending'][0]??null;include __DIR__.'/includes/header.php';if($featured):?><section class="hero" style="background-image:linear-gradient(90deg,var(--bg),transparent),url('<?=e($featured['banner']?:$featured['poster']?:'assets/placeholder.svg')?>')"><div class="hero-copy"><span class="eyebrow">FEATURED ANIME</span><h1><?=e($featured['title'])?></h1><p><?=e(mb_strimwidth($featured['synopsis']??'',0,260,'…'))?></p><div class="meta">★ <?=e($featured['score']?:'—')?> · <?=e($featured['type']?:'Anime')?> · <?=e($featured['year']?:'—')?></div><br><a class="btn" href="<?=url('watch.php?id='.$featured['id'])?>">Watch Now</a> <a class="btn alt" href="<?=url('anime.php?id='.$featured['id'])?>">Details</a></div><img class="poster" src="<?=e($featured['poster']?:'assets/placeholder.svg')?>" alt="<?=e($featured['title'])?>"></section><?php endif;foreach($sections as $name=>$items):?><section class="section"><h2><?=e($name)?></h2><div class="grid"><?php foreach($items as $a)card($a);?></div></section><?php endforeach;include __DIR__.'/includes/footer.php';
